      names=t(['None','Physical','Absorb','Fire','Ice','Lightning','','','Vs sleep','Light','Dark','Double bleeding','Helbreath','Against beasts','Vs Jabberwock','Double stun','Vs vulnerability','Falling','Vs poison','Vs rapiers'],
