      if actor && x.is_a?(RPG::Skill) && x.id==actor.attack_skill_id && x.for_one? && x.for_opponent? && !x.for_random?
        lines << t('This is the current normal attack: target repeats x','This is the current normal attack: target repeats x')+(1+actor.atk_times_add.to_i).to_s+'.'
      end
      lines << t('Use: ','Use: ')+t(['Battle and field','Battle only','Field only','Cannot be used directly'],['Battle and field','Battle only','Field only','Cannot be used directly'])[x.occasion]
