      else
        lines << t('Regular action: takes an action slot.','Regular action: takes an action slot.') if x.battle_ok?
      end
      if actor && x.is_a?(RPG::Item)
        reasons=[]
        reasons << t('not in inventory','not in inventory') if $game_party.item_number(x)==0
        reasons << t('user cannot act','user cannot act') unless actor.movable?
        reasons << t('wrong battle/field context','wrong battle/field context') unless actor.occasion_ok?(x)
        reasons << t('item command sealed','item command sealed') if $game_party.in_battle && actor.item_command_seal?
        reasons << t('instant-use limit reached','instant-use limit reached') if q && q[1]>=q[0]
        lines << t('Current restrictions: ','Current restrictions: ')+reasons.join('; ')+'.' unless reasons.empty?
      end
      if x.is_a?(RPG::Skill)
        if (m=/<クールタイム:(\d+)>/.match(x.note))
          lines << t('Cooldown: initial counter ','Cooldown: initial counter ')+(m[1].to_i+1).to_s+(actor ? t('; remaining now ','; remaining now ')+read_cooldown(x).to_s : '')+'.'
          lines << t('Counter falls by 1 at turn end. It is not the number of future skipped turns.','Counter falls by 1 at turn end. It is not the number of future skipped turns.')
        else
          lines << t('Cooldown: none.','Cooldown: none.')
        end
        required=[x.required_wtype_id1,x.required_wtype_id2].reject { |id| id==0 }
        lines << t('Required weapon types (either): ','Required weapon types (either): ')+required.map { |id| weapon_type(id) }.join(' / ') unless required.empty?
        if actor
          lines << (actor.skill_learn?(@object) ? t('Permanently learned.','Permanently learned.') : t('Not permanently learned.','Not permanently learned.'))
          sources=actor.equips.compact.select { |eq| eq.features.any? { |f| f.code==43 && f.data_id==@object.id } }
