    def effect_lines(item,expanded=true)
      lines=[]
      item.effects.each do |e|
        id=e.data_id;v=e.value1;w=e.value2
        case e.code
        when 11,12
          resource=e.code==11 ? 'HP' : 'MP'
          base=(e.code==11 ? 'MaxHP' : 'MaxMP')+' * '+n(v)+' + '+n(w)
          multiplier='REC'+(item.is_a?(RPG::Item) ? ' * PHA' : '')
          lines << t('Recovery ','Recovery of ')+resource+': trunc(('+base+') * '+multiplier+').'
          lines << t('REC is the target recovery rate; PHA is the user item effectiveness. Negative values cause damage.','REC is the target recovery rate; PHA is the user item effectiveness. Negative values cause damage.')
          lines << t('Target recovery immunity or reversal can cancel or invert healing.','Target recovery immunity or reversal can cancel or invert healing.')
        when 13
          lines << t('Target: TP +','Target: TP +')+v.to_i.to_s+'.'
        when 21
          if id==0
            lines << t('Apply normal attack states: base ','Apply normal attack states: base ')+pct(v)+t(' × attack-state rate × target state rate × luck.',' × attack-state rate × target state rate × luck.')
            if actor
              actor.atk_states.each { |sid| lines << '  '+tagged($data_states[sid])+': '+pct(actor.atk_states_rate(sid)) }
            end
          else
            chance=pct(v)
            chance+=t(' × target state rate',' × target state rate') unless item.note.include?('<有効度無視ステート付与>') || item.note.include?('<強制付与>')
            chance+=t(' × luck',' × luck') unless item.note.include?('<運無視ステート付与>') || item.note.include?('<強制付与>')
            lines << t('Apply ','Apply ')+tagged($data_states[id])+': '+chance+'.'
            lines << t('For ordinary state effects, state-rate and luck multipliers apply only to opponents. State immunity is checked separately.','For ordinary state effects, state-rate and luck multipliers apply only to opponents. State immunity is checked separately.')
            lines += state_lines($data_states[id]) if expanded && $data_states[id]
          end
        when 22
          lines << t('Remove ','Remove ')+tagged($data_states[id])+': '+pct(v)+'.'
        when 31,32
          lines << (e.code==31 ? t('Buff ','Buff ') : t('Debuff ','Debuff '))+param(id)+': '+v.to_i.to_s+t(' turns; 25% per stack, up to 2 stacks.',' turns; 25% per stack, up to 2 stacks.')
          if e.code==32
            lines << t('Chance: target debuff rate','Chance: target debuff rate')+((item.note.include?('<運無視弱体付与>') || item.note.include?('<強制付与>')) ? '.' : t(' × luck.',' × luck.'))
          end
        when 33,34
          lines << (e.code==33 ? t('Remove buff ','Remove buff ') : t('Remove debuff ','Remove debuff '))+param(id)+'.'
        when 41
          lines << t('Target leaves battle (escape).','Target leaves battle (escape).')
        when 42
          lines << t('Permanent base stat increase: ','Permanent base stat increase: ')+param(id)+' +'+v.to_i.to_s+'.'
        when 43
          lines << t('Learn skill: ','Learn skill: ')+tagged($data_skills[id])+'.'
          lines << (actor && actor.skill_learn?($data_skills[id]) ? t('Already learned by this actor.','Already learned by this actor.') : t('An equipment-granted skill is not permanent learning.','An equipment-granted skill is not permanent learning.'))
        when 44
          lines += event_lines(id)
        else
          lines << t('Additional effect needs review: ','Additional effect needs review: ')+[e.code,id,v,w].join(', ')
        end
      end
      lines
    end
    def state_lines(state)
      lines=[]
      restrictions=t(['No action restriction','Attacks an enemy','Attacks a random side','Attacks an ally','Cannot act'],['No action restriction','Attacks enemies','Attacks either side','Attacks allies','Cannot act'])
      lines << '  '+(restrictions[state.restriction] || '?')+'.' if state.restriction>0
      if state.auto_removal_timing>0
        lines << '  '+t('Duration counter: ','Duration counter: ')+state.min_turns.to_s+'..'+state.max_turns.to_s+
          (state.auto_removal_timing==1 ? t('; removal after action.','; removal after action.') : t('; removal at turn end.','; removal at turn end.'))
        lines << '  '+t('ATB may decrease duration before an action; this does not promise N player turns.','ATB may decrease duration before an action; this does not promise N player turns.')
      end
      lines << '  '+t('Removed at battle end.','Removed at battle end.') if state.remove_at_battle_end
      lines << '  '+t('Removal chance on damage: ','Removal chance on damage: ')+state.chance_by_damage.to_s+'%.' if state.remove_by_damage
      lines << '  '+t('Walking removal after ','Walking removal after ')+state.steps_to_remove.to_s+t(' steps.',' steps.') if state.remove_by_walking
      state.features.each { |f| lines << '  '+feature_line(f) }
      lines += note_rules(state).map { |line| '  '+line }
      state.note.scan(/<反撃スキル\s*(\d+)\s*>/).each { |m| lines << '  '+t('Counterattack replaced by ','Counterattack replaced by ')+tagged($data_skills[m[0].to_i]) }
      state.note.scan(/<強制自然解除時ステート[:：]([^>]+)>/).each do |m|
        lines << '  '+t('On natural expiry adds: ','On natural expiry adds: ')+m[0].split(',').map { |s| tagged($data_states[s.to_i]) }.join(', ')+t(' (except battle-end cleanup).',' (except battle-end cleanup).')
      end
      state.note.scan(/<全回避時スキル[:：](\d+)(?:,([^>]+))?>/).each { |id,chance| lines << '  '+t('After evading an opponent: ','After evading an opponent: ')+tagged($data_skills[id.to_i])+'; '+(chance || '100')+t('% if usable; pays its cost.','% if usable; pays its cost.') }
      lines << '  '+t('Seals the item command.','Seals the item command.') if state.note.include?('<アイテム封印>')
      lines
    end
    def feature_line(f)
      id=f.data_id;v=f.value
      case f.code
      when 11;t('Element damage rate ','Element damage rate ')+element(id)+' x'+n(v)
      when 12;t('Debuff rate ','Debuff rate ')+param(id)+' x'+n(v)
      when 13;t('State rate ','State rate ')+tagged($data_states[id])+' x'+n(v)
      when 14;t('Immune: ','Immune: ')+tagged($data_states[id])
      when 21;param(id)+' x'+n(v)
      when 22
        labels=t(['Hit rate','Evasion','Critical chance','Critical evasion','Magic evasion','Magic reflection','Counterattack','HP regeneration','MP regeneration','TP regeneration'],['Hit','Evasion','Critical chance','Critical evasion','Magic evasion','Magic reflection','Counterattack','HP regeneration','MP regeneration','TP regeneration'])
        (labels[id] || '?')+' '+(v>=0 ? '+' : '')+pct(v)
      when 23
        labels=t(['Target rate TGR','Guard effectiveness GRD','Recovery REC','Item effectiveness PHA','MP cost MCR','TP gain TCR','Physical damage PDR','Magic damage MDR','Floor damage FDR','Experience EXR'],['Target rate TGR','Guard strength GRD','Recovery REC','Item effectiveness PHA','MP cost MCR','TP charge TCR','Physical damage PDR','Magic damage MDR','Floor damage FDR','Experience EXR'])
        (labels[id] || '?')+' x'+n(v)
      when 31;t('Normal attack element: ','Normal attack element: ')+element(id)
      when 32;t('Normal attack state: ','Normal attack state: ')+tagged($data_states[id])+' '+pct(v)
      when 33;t('Normal attack speed +','Normal attack speed +')+n(v)
      when 34;t('Extra normal attack repeats: ','Extra normal attack repeats: ')+n(v)
      when 41;t('Grants skill type #','Grants skill type #')+id.to_s
      when 42;t('Seals skill type #','Seals skill type #')+id.to_s
      when 43;t('Grants skill: ','Grants skill: ')+tagged($data_skills[id])
      when 44;t('Seals skill: ','Seals skill: ')+tagged($data_skills[id])
      when 51;t('Allows weapon type #','Allows weapon type #')+id.to_s
      when 52;t('Allows armor type #','Allows armor type #')+id.to_s
      when 53;t('Locks equipment type #','Locks equipment type #')+id.to_s
      when 54;t('Seals equipment type #','Seals equipment type #')+id.to_s
      when 55;t('Slot type: ','Slot type: ')+id.to_s
      when 61;t('Independent extra-action chance: ','Independent extra-action chance: ')+pct(v)
      when 62;t(['Auto battle','Guard','Substitutes an ally','Preserve TP'],['Auto battle','Guard','Substitute','Preserve TP'])[id] || '?'
      when 63;t('Collapse type #','Collapse type #')+id.to_s
      when 64;t('Party ability #','Party ability #')+id.to_s
      else;t('Unmapped feature: ','Unmapped feature: ')+[f.code,id,v].join(', ')
      end
    end
    def effects
      x=@resolved;lines=effect_lines(x)
      lines << t('No direct listed effects. See damage and rules.','No direct listed effects. See damage and rules.') if lines.empty?
      lines << t('Effects apply in order after a hit, for each repeat. A common event is reserved once on use.','Effects apply in order after a hit, for each repeat. A common event is reserved once on use.')
      lines << t('User gains on each hit: TP +','User gains on each hit: TP +')+x.tp_gain.to_s+' * TCR.' if x.tp_gain!=0
      lines << t('Luck: max(1 + (user LUK - target LUK) * 0.001, 0).','Luck: max(1 + (user LUK - target LUK) * 0.001, 0).')
      lines
    end
    def damage
      x=@resolved;d=x.damage;lines=[]
      types=t(['No separate formula damage','HP damage','MP damage','HP recovery','MP recovery','HP drain','MP drain'],['No separate formula damage','HP damage','MP damage','HP recovery','MP recovery','HP drain','MP drain'])
      lines << (types[d.type] || '?')+'.'
      if d.type!=0
        lines << t('Base formula per hit:','Base formula per hit:')
        lines << d.formula
        readable=d.formula.gsub(/\b([ab])\.(mhp|mmp|atk|def|mat|mdf|agi|luk)\b/) do
          side=$1;stat=$2;id={'mhp'=>0,'mmp'=>1,'atk'=>2,'def'=>3,'mat'=>4,'mdf'=>5,'agi'=>6,'luk'=>7}[stat]
          param(id)+t(side=='a' ? ' user' : ' target',side=='a' ? ' of user' : ' of target')
        end
        lines << readable if readable!=d.formula
        lines << t('a = user; b = target; v[n] = game variable. max(formula, 0); recovery reverses the sign.','a = user; b = target; v[n] = game variable. max(formula, 0); recovery reverses the sign.')
        stats={'mhp'=>0,'mmp'=>1,'atk'=>2,'def'=>3,'mat'=>4,'mdf'=>5,'agi'=>6,'luk'=>7}
        d.formula.scan(/\b([ab])\.([a-z_]+)\b/).uniq.each do |side,stat|
          next if stat=='state'
          labels={'hp'=>t('current HP','current HP'),'mp'=>t('current MP','current MP'),'tp'=>t('current TP','current TP'),'level'=>t('level','level')}
          label=stats.has_key?(stat) ? param(stats[stat]) : (labels[stat] || stat.upcase)
          value=actor && side=='a' && (stats.has_key?(stat) || ['hp','mp','tp','level'].include?(stat)) ? ' = '+n(actor.send(stat)) : ''
          lines << side+'.'+stat+': '+t(side=='a' ? 'user, ' : 'target, ',side=='a' ? 'user, ' : 'target, ')+label+value
        end
        d.formula.scan(/([ab])\.state\?\((\d+)\)\s*\?\s*(\d+)\s*:\s*(\d+)/).each do |side,id,yes,no|
          lines << t('Conditional multiplier: if ','Conditional multiplier: if ')+t(side=='a' ? 'user ' : 'target ',side=='a' ? 'user has ' : 'target has ')+tagged($data_states[id.to_i])+' -> x'+yes+t(', otherwise x',', otherwise x')+no+'.'
        end
        lines << t('[expression, cap].min takes the smaller value: an upper cap on the multiplier.','[expression, cap].min takes the smaller value: an upper cap on the multiplier.') if d.formula.include?('].min')
        lines << t('Ruby integer division rounds down at each integer division. Target numbers are in Forecast, without executing arbitrary Ruby code.','Ruby integer division rounds down at each integer division. Target numbers are in Forecast, without executing arbitrary Ruby code.')
        lines << t('Element: ','Element: ')+(d.element_id<0 ? t('normal attack elements; uses the highest target rate.','normal attack elements; uses the highest target rate.') : element(d.element_id)+'.')
        lines << t('Current user attack elements: ','Current user attack elements: ')+actor.atk_elements.map { |id| element(id) }.join(', ')+'.' if d.element_id<0 && actor
        lines << t('Order: formula > element > PDR/MDR > REC for recovery > critical > variance > Guard > integer.','Order: formula > element > PDR/MDR > REC for recovery > critical > variance > Guard > integer.')
        lines << t('PDR applies only to physical hit type; MDR only to magical hit type. Element is a separate multiplier.','PDR applies only to physical hit type; MDR only to magical hit type. Element is a separate multiplier.')
        crit=Hi_ru_Difficulty::DIFFICULTY_SETTING[11][$game_variables[Hi_ru_Difficulty::VARIABLES]]
        lines << (d.critical ? t('Can crit: chance = user CRI * (1 - target CEV); damage x','Can crit: chance = user CRI * (1 - target CEV); damage x')+n(crit)+'.' : t('This record cannot crit.','This record cannot crit.'))
        lines << t('Variance: ±','Variance: +/-')+d.variance.to_s+t('% with a triangular distribution (sum of two rolls).','% with a triangular distribution (sum of two rolls).')
        lines << t('Target Guard divides positive damage by 2 * GRD unless Guard bypass succeeds.','Target Guard divides positive damage by 2 * GRD unless Guard bypass succeeds.')
      end
      lines << t('Hit type: ','Hit type: ')+t(['Certain base','Physical','Magical'],['Base certain hit','Physical','Magical'])[x.hit_type]+'.'
      hit=n(x.success_rate)+'%'+(x.physical? ? ' * HIT' : '')
      lines << t('Success check: ','Success check: ')+hit+t('; then ','; then ')+(x.physical? ? t('target EVA.','target EVA.') : (x.magical? ? t('target MEV.','target MEV.') : t('no ordinary evasion.','no ordinary evasion.')))
      lines << t('Absolute-hit/evasion traits can override these checks; this build prioritizes absolute hit.','Absolute-hit/evasion traits can override these checks; this build prioritizes absolute hit.')
      lines << t('A skill may be cancelled by immunity to its specific ID, checked before hit rolls.','A skill may be cancelled by immunity to its specific ID, checked before hit rolls.') if x.is_a?(RPG::Skill)
      counter=x.note.include?('<反撃不可>') ? false : (x.note.include?('<反撃可能>') || x.physical?)
      lines << (counter ? t('An opponent may counter using CNT.','An opponent may counter using CNT.') : t('Does not trigger normal counterattacks.','Does not trigger normal counterattacks.'))
      lines << t('Magic may be reflected using target MRF.','Magic may be reflected using target MRF.') if x.magical?
      lines << t('No exact damage without a target: its defenses, states and resistances affect the result.','No exact damage without a target: its defenses, states and resistances affect the result.') unless d.type==0
      lines
    end
    def note_rules(x)
      note=x.note;lines=[]
      note.scan(/<防御状態無視率[:：]([^>]+)>/).each { |m| lines << t('Guard bypass threshold: ','Guard bypass threshold: ')+m[0]+t('% + user passive sources. This tag controls Guard separately from DEF in the formula.','% + user passive sources. This tag controls Guard separately from DEF in the formula.') }
      note.scan(/<ダメージ率貫通追加[:：]([^>]+)>/).each { |m| lines << t('Additional PDR/MDR penetration: ','Additional PDR/MDR penetration: ')+m[0]+'%.' }
      note.scan(/<ダメージ率貫通[:：](\d+),([^>]+)>/).each do |type,value|
        if x.is_a?(RPG::UsableItem)
          lines << t('Passive penetration tag: ','Passive penetration tag: ')+type+', '+value+t('%. On a skill/item it has no standalone effect: this tag is read only from the user feature objects.','%. On a skill/item it has no standalone effect: this tag is read only from the user feature objects.')
        else
          lines << t('Penetration through ','Penetration through ')+(type=='1' ? 'PDR ' : 'MDR ')+value+'%.'
        end
      end
      note.scan(/<(?:全|必中|物理|魔法)絶対(?:命中|回避)>|<絶対命中>/).each do |tag|
        labels={'全'=>t('all types','all types'),'必中'=>t('base certain','base certain'),'物理'=>t('physical','physical'),'魔法'=>t('magical','magical')}
        label=labels.find { |key,val| tag.include?(key) }
        lines << (tag.include?('回避') ? t('Absolute evasion: ','Absolute evasion: ') : t('Absolute hit: ','Absolute hit: '))+(label ? label[1] : t('this action','this action'))+'.'
      end
      note.scan(/<スキル無効[:：](\d+)(?:,([^>]+))?>/).each { |sid,chance| lines << t('Cancels incoming skill ','Cancels incoming skill ')+tagged($data_skills[sid.to_i])+t('; threshold ','; threshold ')+(chance || '100')+'%.' }
      ['HP','MP','TP'].each do |resource|
        note.scan(/<#{resource}変換攻撃[:：]([^>]+)>/).each { |m| lines << t('User conversion to ','User conversion to ')+resource+': '+m[0]+t(' (percent of HP damage, chance). Requires the action conversion roll.',' (percent of HP damage, chance). Requires the action conversion roll.') }
      end
      note.scan(/<変換攻撃判定[:：]([^>]+)>/).each { |m| lines << t('Damage conversion trigger chance: ','Damage conversion trigger chance: ')+m[0]+'%.' }
      ['HP','MP'].each do |resource|
        [['回復無効',t('recovery immunity','recovery immunity')],['回復反転',t('recovery reversal','recovery reversal')]].each do |tag,label|
          note.scan(/<#{resource}#{tag}[:：]([^>]+)>/).each { |m| lines << resource+': '+label+' '+m[0]+'%.' }
        end
      end
      lines
    end
    def rules
      x=@resolved;lines=note_rules(x)
      x.note.scan(/<使用者効果\s*(\d+)\s*>/).each do |m|
        linked=$data_skills[m[0].to_i];next unless linked
        lines << t('After battle use, separately applies to the user: ','After battle use, separately applies to the user: ')+tagged(linked)
        lines += effect_lines(linked,false).map { |s| '  '+s }
        lines << '  '+t('Also formula: ','Also formula: ')+linked.damage.formula unless linked.damage.none?
      end
      @object.note.scan(/<ステート変化:(\d+),(\d+)>/).each do |sid,state|
        lines << t('With state ','With state ')+tagged($data_states[state.to_i])+t(' select ',' select ')+tagged($data_skills[sid.to_i])+'.'
      end
      lines << t('If multiple conditions match, the last match wins. The variant is fixed when the command is selected.','If multiple conditions match, the last match wins. The variant is fixed when the command is selected.') if @object.note.include?('<ステート変化:')
      x.note.scan(/<使用後追加行動[:：]([^>]+)>/).each do |m|
        parts=m[0].split(',');sid=parts[0];target=parts[1];threshold=parts[2] || '100'
        linked=/\A\d+\z/ =~ sid ? $data_skills[sid.to_i] : nil
        chance=/\A-?\d+(?:\.\d+)?\z/ =~ threshold ? [[threshold.to_f.floor+1,0].max,100].min.to_s+'%' : t('expression ','expression ')+threshold
        lines << t('Follow-up action after use: ','Follow-up action after use: ')+(linked ? tagged(linked) : sid)+t('; chance ','; chance ')+chance+'.'
        lines << t('Target: ','Target: ')+(target=='-2' ? t('last selected target.','last selected target.') : (target=='-1' ? t('random.','random.') : t('index ','index ')+target.to_s+'.'))
        lines << t('Inserted into the queue only if the user can act; has its own requirements and costs.','Inserted into the queue only if the user can act; has its own requirements and costs.')
        if linked
          lines << '  '+t('Formula: ','Formula: ')+linked.damage.formula unless linked.damage.none?
          lines += effect_lines(linked,false).map { |s| '  '+s }
        end
        lines << t('Script detail: threshold 50 gives 51%; threshold 0 gives 1% (inclusive roll 0..99).','Script detail: threshold 50 gives 51%; threshold 0 gives 1% (inclusive roll 0..99).') if threshold!='100'
      end
      x.note.scan(/<(行動後遅延発動|遅延発動)[:：]([^>]+)>/).each do |tag,value|
        parts=value.split(',').map { |s| s.to_i };linked=x.is_a?(RPG::Skill) ? $data_skills[parts[1]] : $data_items[parts[1]]
        lines << t('Delayed use: ','Delayed use: ')+tagged(linked)+t('; counter ','; counter ')+parts[2].to_s+'..'+(parts[2]+(parts[3] || 0)).to_s+t('; chance ','; chance ')+(parts[4] || 100).to_s+'%.'
        lines << (tag=='行動後遅延発動' ? t('Counter checked after the target actions.','Counter checked after the target actions.') : t('Counter checked at turn end.','Counter checked at turn end.'))+t(' Checks <= 0 before decreasing: initial N triggers on check N+1.',' Checks <= 0 before decreasing: initial N triggers on check N+1.')
        lines << t('Does not fire if the target died or disappeared.','Does not fire if the target died or disappeared.')
      end
      lines << t('Cannot be put in storage (this does not prevent saving the game).','Cannot be put in storage (this does not prevent saving the game).') if x.note.include?('<保存禁止>')
      x.note.scan(/ステルス:(\d+)/).each { |m| lines << t('Stealth against map enemies: ','Stealth against map enemies: ')+m[0]+t(' steps.',' steps.') }
      if actor
        sources=actor.feature_objects
        penetration=sources.map { |f| f.note.scan(/<ダメージ率貫通[:：]#{x.hit_type},([^>]+)>/).flatten }.flatten
        lines << t('PDR/MDR penetration from current traits: ','PDR/MDR penetration from current traits: ')+penetration.join(' + ')+'%.' unless penetration.empty? || x.hit_type==0
        guard=sources.map { |f| f.note.scan(/<パッシブ防御状態無視率[:：]([^>]+)>/).flatten }.flatten
        guard+=actor.skills.map { |f| f.note.scan(/<パッシブ防御状態無視率[:：]([^>]+)>/).flatten }.flatten
        lines << t('Current passive Guard bypass: ','Current passive Guard bypass: ')+guard.join(' + ')+'%.' unless guard.empty?
      end
      lines << t('Event-dependent restrictions cannot all be reduced to combat numbers; conditional effects are marked separately.','Event-dependent restrictions cannot all be reduced to combat numbers; conditional effects are marked separately.') if x.effects.any? { |e| e.code==44 }
      lines << t('Penetration: when PDR/MDR < 1, use 1 - (1 - original rate) * (100 - penetration) / 100, clamped to 0..1.','Penetration: when PDR/MDR < 1, use 1 - (1 - original rate) * (100 - penetration) / 100, clamped to 0..1.') unless x.damage.none?
      lines << t('The reference applies nothing, rolls no random numbers and does not calculate action order.','The reference applies nothing, rolls no random numbers and does not calculate action order.')
      lines
    end
    def event_lines(id)
      event=$data_common_events[id]
      return [t('Missing event #','Missing event #')+id.to_s] unless event
      meaningful=event.list.reject { |c| [0,101,401,250,230].include?(c.code) }
      if meaningful.size==1 && meaningful[0].code==125 && meaningful[0].parameters[1]==0
        p=meaningful[0].parameters
        return [t('Gain souls: ','Gain souls: ')+(p[0]==0 ? '+' : '-')+p[2].to_s+'.']
      end
      pair=event_summary(id)
      [t('Event #','Event #')+id.to_s+': '+(pair ? t(pair[0],pair[1]) : t('Depends on map/story/encounter; the full outcome has not yet been decoded.','Depends on map/story/encounter; the full outcome has not yet been decoded.'))]
    end
    def event_summary(id)
      case id
      when 3;['Returns to a bonfire; restrictions and special locations depend on progress and map.','Return to bonfire; restrictions and special destinations depend on progress and map.']
      when 13;['Requests ally summons through a battle event. Party composition depends on the encounter.','Requests ally summoning via battle events. Allies depend on the encounter.']
      when 17;['Adds 10 of item #57.','Adds 10 copies of item #57.']
      when 18;['If souls lost on death are recorded, restores their saved amount and clears the loss marker. Otherwise returns the spent card.','If lost souls exist, restores their stored amount and clears the lost-souls marker. Otherwise refunds the card.']
      when 31;['Enables stealth and resets steps. Duration is set by the particular item / skill.','Enables stealth and resets steps. Duration comes from the specific item/skill.']
      when 36;['Loses all held souls and transfers to the Library Dream. Story restrictions may stop the event; transfer also resets field flags.','Loses all held souls and transfers to Library Dream. Story restrictions can stop the event; the transfer also resets field flags.']
      when 37;['Enables preparation and interruptible charge flags. Response depends on the battle event.','Enables charge and interruptible-charge flags. Reactions depend on battle events.']
      when 38;['Clears the interruptible charge flag.','Clears the interruptible-charge flag.']
      when 41;['Menu for toggling hint display.','Opens the show/hide advice menu.']
      when 43;['Selects normal or increased movement speed.','Selects normal or fast movement speed.']
      when 44;['Adds state #44 to all enemies.','Adds state #44 to all enemies.']
      when 47;['SEN -30.','SEN -30.']
      when 48;['Reduces all allies\' cooldown counters by 5.','Reduces all ally cooldown counters by 5.']
      when 58;['On map #54, transfers to map #136; no transfer elsewhere.','Transfers from map #54 to map #136; no transfer elsewhere.']
      when 59;['On map #136, transfers to map #54; no transfer elsewhere.','Transfers from map #136 to map #54; no transfer elsewhere.']
      when 60;['Enables a battle disguise flag; the encounter defines the response.','Enables the battle disguise flag; the encounter defines the response.']
      when 61;['Enables an end-disguise flag; the encounter defines the response.','Sets the end-disguise flag; the encounter defines the response.']
      when 62,63;['Disables enemy in slot '+(id==62 ? '2' : '3')+'.','Incapacitates the enemy in slot '+(id==62 ? '2' : '3')+'.']
      when 64,66;['Disables enemy in slot '+(id==64 ? '4' : '1')+'.','Incapacitates the enemy in slot '+(id==64 ? '4' : '1')+'.']
      when 65;['Clears the charge flag, applies state #37 to all enemies and restores enemy in slot 1.','Clears the charge flag, applies state #37 to all enemies and fully recovers enemy slot 1.']
      when 72;['Removes 10000 HP from all enemies; can kill.','Subtracts 10000 HP from all enemies, allowing death.']
      when 210;['Adds state #29 to enemy in slot 1.','Adds state #29 to enemy slot 1.']
      when 218;['Reduces all allies\' cooldown counters by 99. Does not unconditionally reset every possible counter.','Reduces all ally cooldown counters by 99. This is not unconditional clearing of every possible counter.']
      when 220;['Per item: base MaxHP +300, MaxMP +150, other parameters +30; SEN +100. Quantity selection and confirmation.','Per item: base max HP +300, MP +150, other stats +30; SEN +100. Quantity choice and confirmation.']
      when 221;['Per item: base MaxHP +10, MaxMP +5, other parameters +1; SEN −10. Quantity selection and confirmation.','Per item: base max HP +10, MP +5, other stats +1; SEN -10. Quantity choice and confirmation.']
      when 222;['Per item: base MaxHP +30, MaxMP +15, other parameters +3; SEN −30. Quantity selection and confirmation.','Per item: base max HP +30, MP +15, other stats +3; SEN -30. Quantity choice and confirmation.']
      when 223..230
        index=[0,1,2,3,6,4,5,7][id-223];amount=index==0 ? 20 : (index==1 ? 10 : 2)
        ['Per item: base '+param(index)+' +'+amount.to_s+'. Increases the base bonus; totals include multipliers. Quantity selection.','Per item: base '+param(index)+' +'+amount.to_s+'. Increases the base bonus; final stats include multipliers. Quantity choice.']
      when 231;['SEN +30 per item. Quantity selection and confirmation.','SEN +30 per item. Quantity choice and confirmation.']
      when 232;['SEN −10 per item. Quantity selection and confirmation.','SEN -10 per item. Quantity choice and confirmation.']
      when 233;['Level +5 per item up to the actor\'s maximum. Quantity selection; the last item may grant fewer than 5 levels.','+5 levels per item, capped at actor maximum. Quantity choice; the last item may grant fewer than 5 levels.']
      when 234;['Menu: set SEN to 100 or 0; can be canceled.','Menu: set SEN to 100 or 0; can cancel.']
      when 288;['Old King\'s return: special transfer, recovery and progress changes according to event conditions. The full transition is not simulated here.','Old King return: special transfer, recovery and progress changes controlled by event conditions. The transition is not simulated here.']
      when 292;['Unequips slots 1..7 for actors 1..11; weapon in slot 0 is retained.','Removes equipment in slots 1..7 from actors 1..11; weapon slot 0 is retained.']
      when 293;['Enables flag #31 for the current encounter to process. Result depends on the battle event.','Sets flag #31 for the current encounter to process. The battle event determines the outcome.']
      when 299;['Transfer through event #276; the item is returned if a special story restriction applies.','Transfer via event #276; a special story restriction refunds the item.']
      when 344;['Sets SEN to 100.','Sets SEN to 100.']
      when 345;['Wall of Flesh summon: checks summon availability and event restriction; adds ally #111 with state #167. Additional states depend on story flags.','Flesh Wall summon: checks existing summon and event limit; adds ally #111 with state #167. Additional states depend on story flags.']
      when 350;['Unequips slot 3 (body) for actors 1..11.','Removes body-slot equipment (slot 3) from actors 1..11.']
      else;nil
      end
    end
  end
end
